.chat-home{min-height:100vh;background:#f5f1e9 url('/assets/ai-search-background.webp') center / cover no-repeat}
.chat-stage{min-height:calc(100vh - 74px);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:20px;padding:24px 16px 48px;text-align:center}
.chat-stage h1{margin:0;font-size:36px;line-height:45px;font-weight:500;letter-spacing:-.03em}
.chat-stage>p,.entry-intro p{margin:0;font-size:16px;line-height:24px;color:#4b4b52}
.entry-intro{display:grid;justify-items:center;gap:8px}
.chat-label{margin:0;font-size:12px;color:var(--muted)}
.chat-examples{display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:0;width:min(720px,100%);text-align:left}
.chat-examples button{border:0;background:transparent;color:#5e6067;padding:4px 0;font-size:13px;line-height:20px}
.chat-composer{width:min(720px,100%);min-height:106px;background:#fff;border:1px solid #d9d9de;border-radius:24px;padding:16px 20px;box-shadow:0 8px 24px rgb(0 0 0 / .06);text-align:left}
.chat-composer textarea{display:block;width:100%;border:0;resize:none;background:transparent;min-height:32px;font-size:13px;line-height:20px}
.chat-tools{display:flex;align-items:center;gap:8px;margin-top:12px}
.chat-chip{border:1px solid var(--line);border-radius:999px;padding:4px 10px;font-size:12px;white-space:nowrap}
.chat-tools button{margin-left:auto;width:28px;height:28px;border:0;border-radius:999px;padding:0;background:#18181b;color:#fff}
.chat-thread{width:min(720px,100%);text-align:left;display:flex;flex-direction:column;gap:10px}
.chat-turn p{display:inline-block;max-width:92%;margin:0;padding:8px 12px;border:1px solid var(--line);border-radius:12px;background:#fff;line-height:1.45}
.chat-turn.is-buyer{text-align:right}.chat-turn small{display:block;margin-top:4px;color:var(--muted);font-size:10px}
.chat-panel{position:fixed;top:0;right:0;bottom:0;z-index:4;width:var(--chat-w);display:flex;flex-direction:column;gap:8px;padding:12px;background:var(--ground);border-left:1px solid var(--line);overflow:hidden}
.chat-panel header{display:flex;align-items:center;justify-content:space-between}.chat-panel header button{border:0;background:transparent}
.chat-panel .chat-thread{width:100%;flex:1;overflow:auto}.chat-panel .chat-composer{width:100%;box-shadow:none}
.chat-examples button{text-align:left;white-space:normal;max-width:100%;overflow-wrap:anywhere}
.chat-stage .chat-turn p{max-width:100%}
.entry-notice{margin:0;padding:8px 14px;border:1px solid var(--line);border-radius:999px;background:#fff;font-size:13px}
.tailor-attribution{margin:0;color:#66656a;font-size:12px;line-height:18px}
.tailor-pill{display:inline-block;margin-left:4px;padding:1px 8px;border:1px solid rgb(68 64 60 / .14);border-radius:999px;background:rgb(255 255 255 / .78);color:#3c3936;font-size:11px;line-height:17px}
.active-tag{margin-left:8px;padding:2px 7px;border:1px solid var(--line);border-radius:999px;font-size:10px;color:var(--ink);background:var(--subtle)}
.ended{max-width:560px;margin:15vh auto 0;padding:0 24px}.ended h1{font-size:28px;font-weight:550;letter-spacing:-.02em;margin:0 0 12px}.ended p{line-height:1.7;color:var(--muted);margin:0 0 22px}.ended .solid{display:inline-flex;text-decoration:none}
