.chat-panel header{display:flex;align-items:center;justify-content:space-between}.chat-panel header button{border:0;background:transparent}
.chat-panel .chat-thread{width:100%;flex:1;overflow:auto}.chat-panel .chat-composer{width:100%;box-shadow:none}
.chat-reopen{margin:8px 16px;align-self:flex-start}
tr.is-active-fixture{background:#f4f8ff}
