.chat-actions{display:flex;align-items:center;gap:6px}
.end-demo{font-size:11px;padding:4px 9px;color:var(--bad);border-color:var(--line)}
.chat-reopen{display:flex;gap:8px;flex-wrap:wrap}
.chat-label.chat-mock{color:#8a5a00}.dark .chat-label.chat-mock{color:#f1d28a}
.chat-panel>.chat-label{margin:-2px 0 0}
.chat-examples button{text-align:left;white-space:normal;max-width:100%;overflow-wrap:anywhere}
.chat-stage .chat-turn p{max-width:100%}
.entry-notice{margin:0;padding:8px 14px;border:1px solid var(--line);border-radius:999px;background:#fff;font-size:13px}
.chat-home .chat-stage{gap:20px}
.chat-home .chat-stage h1{line-height:45px}
.chat-home .entry-intro{display:grid;justify-items:center;gap:8px}
.chat-home .entry-intro p{margin:0;font-size:16px;line-height:24px;color:#4b4b52}
.chat-home .chat-composer{min-height:106px;border-radius:24px;padding:16px 20px}
.chat-home .tailor-attribution{margin:0;color:#66656a;font-size:12px;line-height:18px}
